pub use plan::{ArchivedChangeset, PlannedBump, VersionPlan, VersionWriteTarget};
pub use resolver::{DependencyResolver, ManifestWalkResolver};
pub use tags::TagIndex;
pub use toposort::toposort_impl;

pub struct Workspace<'a, R: CommandRunner, D: DependencyResolver = ManifestWalkResolver> {
    pub root: PathBuf,
    pub config: ResolvedConfig,
    pub graph: D,
    /// Deferred [`TagIndex`]: built at most once, the first time
    /// [`Workspace::tags`] is called, not eagerly by [`Workspace::load`].
    ///
    /// `TagIndex::build` fetches the repo's full tag list with a `git tag
    /// --list` spawn. Several command paths never consult tags at all (`add`'s
    /// non-interactive path only needs [`Workspace::root`]; `init` only
    /// needs package names/root), so building unconditionally in
    /// `Workspace::load` charged every caller for work only some need. All
    }

    fn assemble<L: ProjectLocator>(
        root: PathBuf,
        mut config: ResolvedConfig,
        locator: &L,
        runner: &'a R,
    ) -> Result<Self, GraphError> {
        let manifest_cache: RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>> = RefCell::new(BTreeMap::new());
        let graph = ManifestWalkResolver::build(&root, locator, &config, &manifest_cache)?;

        config.groups = GroupTable::resolve(&config.raw_groups, graph.identity())?;

        let identity = graph.identity().clone();

        Ok(Workspace {
            root,
            config,
            graph,
            tags: OnceCell::new(),
            git: OnceCell::new(),
        runner: &'a CountingBatchRunner,
        packages: Vec<Package>,
    ) -> Workspace<'a, CountingBatchRunner, FixedManifestGraph> {
        let config = crate::config::load(std::path::Path::new("/nonexistent-test-root")).unwrap();
        let graph = FixedManifestGraph { packages };
        Workspace {
            root: std::path::PathBuf::from("/nonexistent-test-root"),
            config,
            graph,
            tags: std::cell::OnceCell::new(),
            git: std::cell::OnceCell::new(),
            runner,
            manifest_cache: Default::default(),
            identity: crate::IdentityIndex::default(),
        }
    }

    let cfg = callisto_graph::config::load(root).unwrap();
    let runner = DummyRunner;
    let identity = identity_for(&graph);
    let ws = callisto_graph::Workspace {
        root: root.to_path_buf(),
        config: cfg,
        graph,
        tags: OnceCell::new(),
        git: OnceCell::new(),
        runner: &runner,
        manifest_cache: Default::default(),
        identity,
